     1	/** The premium office: what the MHPCO charges to take a list of items on risk.
     2	 *  Every decision here belongs to the tariff -- the price list, the building
     3	 *  block, the risk surcharges, the customer's standing, the processing fee, and
     4	 *  the rounding that falls the office's way. It changes when the tariff is
     5	 *  revised, independently of how claims are settled. */
     6	
     7	import { alikeKey, basePremium, type Item } from "./item-catalog.js";
     8	
     9	export interface Customer {
    10	  yearsWithMHPCO: number;
    11	}
    12	
    13	/** The MHPCO price list offers a building block of 3 alike items at a
    14	 *  special base premium instead of the sum of the per-item prices. The
    15	 *  price list states the rule for components; the office has not yet ruled
    16	 *  on whether a block of 3 alike main items is granted the same price. */
    17	const BUILDING_BLOCK_SIZE = 3;
    18	const BUILDING_BLOCK_BASE_PREMIUM = 60;
    19	
    20	const CURSE_SURCHARGE_RATE = 0.5;
    21	const HIGH_ENCHANTMENT_THRESHOLD = 5;
    22	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
    23	const LOYALTY_YEARS_THRESHOLD = 2;
    24	const LOYALTY_DISCOUNT_RATE = 0.2;
    25	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
    26	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
    27	const PROCESSING_FEE = 5;
    28	
    29	/** Whether a group of alike items qualifies for the special building-block
    30	 *  price. The MHPCO grants the block only for a group of exactly 3 -- a
    31	 *  fourth alike item forfeits the special price for the whole group. */
    32	function formsBuildingBlock(alikeItems: Item[]): boolean {
    33	  return alikeItems.length === BUILDING_BLOCK_SIZE;
    34	}
    35	
    36	/** The base premium the price list charges for one group of alike items:
    37	 *  the special block price when the group forms a building block, otherwise
    38	 *  the per-item price of every item in the group. */
    39	function alikeGroupBasePremium(alikeItems: Item[]): number {
    40	  if (formsBuildingBlock(alikeItems)) {
    41	    return BUILDING_BLOCK_BASE_PREMIUM;
    42	  }
    43	  return alikeItems.reduce((sum, item) => sum + basePremium(item), 0);
    44	}
    45	
    46	/** The items of a quote, partitioned into groups of alike items. */
    47	function groupAlikeItems(items: Item[]): Item[][] {
    48	  const groups = new Map<string, Item[]>();
    49	  for (const item of items) {
    50	    const key = alikeKey(item);
    51	    const alike = groups.get(key) ?? [];
    52	    alike.push(item);
    53	    groups.set(key, alike);
    54	  }
    55	  return [...groups.values()];
    56	}
    57	
    58	/** The policy base premium: the sum of the base premiums of all insured
    59	 *  items, before any modifier. */
    60	function policyBasePremium(items: Item[]): number {
    61	  return groupAlikeItems(items).reduce(
    62	    (sum, alikeGroup) => sum + alikeGroupBasePremium(alikeGroup),
    63	    0,
    64	  );
    65	}
    66	
    67	/** A cursed item carries a risk surcharge for that item alone, not for the
    68	 *  policy. */
    69	function isCursed(item: Item): boolean {
    70	  return item.cursed === true;
    71	}
    72	
    73	/** An item counts as highly enchanted from enchantment level 5 upwards. */
    74	function isHighlyEnchanted(item: Item): boolean {
    75	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
    76	}
    77	
    78	/** The risk surcharges an item carries on its own base premium. An item may
    79	 *  carry several risks at once, and the MHPCO charges every one of them in
    80	 *  full: the surcharges accumulate, each measured on the item's *unmodified*
    81	 *  base premium, so a cursed and highly enchanted sword pays 50 % + 30 %. */
    82	function itemRiskSurcharge(item: Item): number {
    83	  const base = basePremium(item);
    84	  const curse = isCursed(item) ? base * CURSE_SURCHARGE_RATE : 0;
    85	  const enchantment = isHighlyEnchanted(item) ? base * HIGH_ENCHANTMENT_SURCHARGE_RATE : 0;
    86	  return curse + enchantment;
    87	}
    88	
    89	/** The risk surcharges of all insured items. */
    90	function policyRiskSurcharge(items: Item[]): number {
    91	  return items.reduce((sum, item) => sum + itemRiskSurcharge(item), 0);
    92	}
    93	
    94	/** How the customer stands with the MHPCO at the moment of this quote: the
    95	 *  length of the business relationship and the number of contracts that
    96	 *  precede this one in the customer's scenario. The policy-wide discounts are
    97	 *  decisions about this standing, not about the insured items. */
    98	export interface CustomerStanding {
    99	  customer: Customer;
   100	  previousContracts: number;
   101	}
   102	
   103	/** A customer is long-standing from 2 years of business with the MHPCO. */
   104	function isLongStanding(standing: CustomerStanding): boolean {
   105	  return standing.customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
   106	}
   107	
   108	/** Every contract after the customer's first earns the follow-up discount. */
   109	function isFollowUpContract(standing: CustomerStanding): boolean {
   110	  return standing.previousContracts >= 1;
   111	}
   112	
   113	/** The net policy-wide modifier, which the MHPCO charges against the
   114	 *  *unmodified* policy base premium -- item risk surcharges do not raise the
   115	 *  amount these modifiers are measured on. All three policy-wide modifiers are
   116	 *  measured on that same base and accumulated here: the initial assessment
   117	 *  surcharge, the loyalty discount, and the follow-up contract discount. Every
   118	 *  quote is treated as a first insurance and carries the initial assessment
   119	 *  surcharge, regardless of customer history -- so a long-standing customer's
   120	 *  follow-up contract for a new item carries both the surcharge and both
   121	 *  discounts. */
   122	function policyModifierAdjustment(policyBase: number, standing: CustomerStanding): number {
   123	  const firstInsurance = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
   124	  const loyalty = isLongStanding(standing) ? policyBase * LOYALTY_DISCOUNT_RATE : 0;
   125	  const followUp = isFollowUpContract(standing)
   126	    ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
   127	    : 0;
   128	  return firstInsurance - loyalty - followUp;
   129	}
   130	
   131	/** The policy premium with all modifiers applied, before the processing fee:
   132	 *  the price-list base premium, plus the risk surcharges the individual items
   133	 *  carry, plus the policy-wide modifiers. */
   134	function modifiedPolicyPremium(items: Item[], standing: CustomerStanding): number {
   135	  const policyBase = policyBasePremium(items);
   136	  return (
   137	    policyBase + policyRiskSurcharge(items) + policyModifierAdjustment(policyBase, standing)
   138	  );
   139	}
   140	
   141	/** The MHPCO rounds every premium in its own favour: to the whole G above. */
   142	function roundedInMHPCOsFavour(premium: number): number {
   143	  return Math.ceil(premium);
   144	}
   145	
   146	/** The settlement the MHPCO bills for a premium it has calculated: the office
   147	 *  adds its processing fee to every premium, last of all and after every
   148	 *  modifier, and then bills the whole G in its own favour. Fee and rounding are
   149	 *  one decision -- what the office charges on top of the calculated risk, and
   150	 *  in whose favour the fraction falls -- and both change independently of how
   151	 *  the premium itself was arrived at. */
   152	function settledPremium(modifiedPremium: number): number {
   153	  return roundedInMHPCOsFavour(modifiedPremium + PROCESSING_FEE);
   154	}
   155	
   156	/** The premium the MHPCO charges a customer for insuring a list of items:
   157	 *  the modified policy premium, settled by the office. */
   158	export function quote(customer: Customer, items: Item[], previousContracts: number): number {
   159	  return settledPremium(modifiedPolicyPremium(items, { customer, previousContracts }));
   160	}
