     1	/** The claims office: what the MHPCO pays out when an insured item is damaged.
     2	 *  Every decision here belongs to the claims handbook -- the deductible, the
     3	 *  special clauses, the cap on a policy -- and is revised independently of the
     4	 *  tariff that priced the policy. */
     5	
     6	import { insuranceValue, type Item } from "./item-catalog.js";
     7	
     8	export interface Damage {
     9	  itemType: string;
    10	  amount: number;
    11	}
    12	
    13	export interface Incident {
    14	  cause: string;
    15	  damages: Damage[];
    16	}
    17	
    18	export interface Policy {
    19	  items: Item[];
    20	  /** What the MHPCO has already paid out on this policy against its cap. */
    21	  capConsumed: number;
    22	}
    23	
    24	export interface ClaimResult {
    25	  payout: number;
    26	  remainingCap: number;
    27	}
    28	
    29	const DEDUCTIBLE_PER_DAMAGE = 100;
    30	
    31	/** The MHPCO never pays out more than twice the sum a policy insures. */
    32	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    33	
    34	/** From enchantment level 8 upwards the handbook reimburses only half the
    35	 *  damage: powerful enchantments are held to attract their own misfortune.
    36	 *  This is the only clause the handbook reads *down* from full reimbursement,
    37	 *  so it outranks the dragon-material clause whenever both cover an item. */
    38	const HIGH_ENCHANTMENT_CLAUSE_THRESHOLD = 8;
    39	const HIGH_ENCHANTMENT_CLAUSE_SHARE = 0.5;
    40	
    41	/** The MHPCO opens a policy over the items a quote covered. */
    42	export function createPolicy(items: Item[]): Policy {
    43	  return { items, capConsumed: 0 };
    44	}
    45	
    46	/** The MHPCO bears its deductible against a damage; it never turns the
    47	 *  deductible round into a charge the customer owes the office. A damage
    48	 *  smaller than the deductible is simply not reimbursed. */
    49	function neverACharge(reimbursement: number): number {
    50	  return Math.max(reimbursement, 0);
    51	}
    52	
    53	/** Whether the handbook's high-enchantment clause covers a damaged item. */
    54	function fallsUnderHighEnchantmentClause(item: Item): boolean {
    55	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAUSE_THRESHOLD;
    56	}
    57	
    58	/** The amount of a damage the handbook reimburses, before the deductible is
    59	 *  kept back. Full reimbursement is what the office grants unless a clause cuts
    60	 *  it down, and the high-enchantment clause is the only clause that cuts.
    61	 *
    62	 *  The handbook's dragon-material clause -- damage to items made of dragon
    63	 *  material is fully reimbursed -- is therefore already honoured here: it grants
    64	 *  exactly what the default grants, so no dragon branch is written. Should a
    65	 *  future clause reduce reimbursement for some *other* reason, dragon material
    66	 *  would have to be read as an exemption from it, and would then need a branch
    67	 *  of its own. */
    68	function reimbursedAmount(damage: Damage, item: Item): number {
    69	  if (fallsUnderHighEnchantmentClause(item)) {
    70	    return damage.amount * HIGH_ENCHANTMENT_CLAUSE_SHARE;
    71	  }
    72	  return damage.amount;
    73	}
    74	
    75	/** The handbook's reimbursement decision for one damage event: the clauses
    76	 *  decide the reimbursed amount, from which the MHPCO keeps back its
    77	 *  deductible. */
    78	function reimbursementForDamage(damage: Damage, item: Item): number {
    79	  return neverACharge(reimbursedAmount(damage, item) - DEDUCTIBLE_PER_DAMAGE);
    80	}
    81	
    82	/** The insured item a reported damage refers to. The office has not yet ruled
    83	 *  on a damage naming an item the policy does not cover. */
    84	function damagedItem(policy: Policy, damage: Damage): Item {
    85	  return policy.items.find((item) => item.type === damage.itemType) as Item;
    86	}
    87	
    88	/** The sum a policy insures: the insurance values of all covered items. The
    89	 *  block discount on the premium does not reduce what the items are insured
    90	 *  for. */
    91	function insuranceSum(policy: Policy): number {
    92	  return policy.items.reduce((sum, item) => sum + insuranceValue(item), 0);
    93	}
    94	
    95	/** The most the MHPCO will ever pay out on a policy. */
    96	function payoutCap(policy: Policy): number {
    97	  return insuranceSum(policy) * CAP_MULTIPLE_OF_INSURANCE_SUM;
    98	}
    99	
   100	/** What the handbook reimburses for a whole incident: every reported damage
   101	 *  settled on its own terms -- its own clauses, its own deductible -- and the
   102	 *  reimbursements added up. This is the claim before the cap is consulted; how
   103	 *  far the policy's cap bounds it is a separate decision. */
   104	function reimbursementForIncident(policy: Policy, incident: Incident): number {
   105	  return incident.damages.reduce(
   106	    (sum, damage) => sum + reimbursementForDamage(damage, damagedItem(policy, damage)),
   107	    0,
   108	  );
   109	}
   110	
   111	/** What is left of a policy's cap: the cap itself, less what the MHPCO has
   112	 *  already paid out on it. */
   113	function remainingCap(policy: Policy): number {
   114	  return payoutCap(policy) - policy.capConsumed;
   115	}
   116	
   117	/** What the MHPCO actually pays for an incident: what the handbook reimburses,
   118	 *  but never more than the policy's cap still allows. A claim that asks for more
   119	 *  than is left is settled at what is left. */
   120	/** The MHPCO rounds every payout in its own favour: to the whole G below. */
   121	function roundedInMHPCOsFavour(payout: number): number {
   122	  return Math.floor(payout);
   123	}
   124	
   125	function settledPayout(policy: Policy, incident: Incident): number {
   126	  const bounded = Math.min(reimbursementForIncident(policy, incident), remainingCap(policy));
   127	  return roundedInMHPCOsFavour(bounded);
   128	}
   129	
   130	/** The office's ledger entry against the policy: a settled payout consumes that
   131	 *  much of the policy's cap, once and for good. This is what makes a claim a
   132	 *  command rather than a calculation -- the cap a later claim finds is the cap
   133	 *  this one left behind. */
   134	function recordAgainstCap(policy: Policy, payout: number): void {
   135	  policy.capConsumed += payout;
   136	}
   137	
   138	/** The MHPCO settles one incident against a policy: it decides what the claim is
   139	 *  worth under the handbook and the policy's remaining cap, enters that payout
   140	 *  in the policy's ledger, and reports the payout with the cap that survives it.
   141	 *  Deciding the amount and recording it are separate acts here, so that a change
   142	 *  to how a payout is arrived at is necessarily also what gets recorded. */
   143	export function claim(policy: Policy, incident: Incident): ClaimResult {
   144	  const payout = settledPayout(policy, incident);
   145	  recordAgainstCap(policy, payout);
   146	  return { payout, remainingCap: remainingCap(policy) };
   147	}
